INSERT INTO `chat_message` VALUES (314,17,3,'Welcome! Share one small idea, ask for help, or take your time. These are demo messages.','54215d9e-e721-433e-afc3-ac89987c8bfa','2026-10-28 03:15:00'),(315,17,2,'Hi everyone! My idea is a small healthy snack stall. What would you try?','fdf2735c-220c-45c0-89a5-8e1fd376c8d1','2026-10-28 03:15:00'),(316,17,92,'I would start with a simple budget. Can someone help me list the costs?','eb21482b-eac0-48ce-b5d5-29a01e42b083','2026-10-28 03:15:00'),(317,17,154,'We can list ingredients, packaging, and transport first. One step at a time.','b565a84d-2437-4fc8-8c19-55acf9f692c8','2026-10-28 03:15:00'),(318,17,155,'I am trying a handmade bookmark idea. I will sketch one design today.','9bbf98e5-719d-44ef-8abf-6e72fd6b62ce','2026-10-28 03:15:00'),(319,17,156,'A small first step helps me. We can share our ideas after the lesson.','54ef4187-7419-44f9-bf9f-57fdba27416b','2026-10-28 03:15:00'),(320,17,157,'Thanks for the ideas! I am still deciding, and I am happy to learn together.','d049205a-c8d5-4efe-9b8f-44b59aacc0b9','2026-10-28 03:15:00'),(321,18,3,'Welcome! Share one small idea, ask for help, or take your time. These are demo messages.','f61b3ed5-e502-4228-85a6-cd2b841c0b85','2026-10-28 03:15:01'),(322,18,2,'Hi everyone! My idea is a small healthy snack stall. What would you try?','829e1484-e9c1-491d-8e99-2369367d2d0b','2026-10-28 03:15:01'),(323,18,92,'I would start with a simple budget. Can someone help me list the costs?','0fb645e5-7248-4578-87f9-f37256169706','2026-10-28 03:15:01'),(324,18,154,'We can list ingredients, packaging, and transport first. One step at a time.','8b20f858-ac61-4843-929f-c22bbdc5cc99','2026-10-28 03:15:01'),(325,19,93,'Welcome! Share one small idea, ask for help, or take your time. These are demo messages.','3fc1b001-7a6b-497b-b530-cf7a18b5e796','2026-10-28 03:15:02'),(326,19,155,'I am trying a handmade bookmark idea. I will sketch one design today.','a5909ac8-9707-4664-b6ef-413eb0153723','2026-10-28 03:15:02'),(327,19,156,'A small first step helps me. We can share our ideas after the lesson.','c6bb8627-ff74-4273-85f0-cfec2ad11634','2026-10-28 03:15:02'),(328,19,157,'Thanks for the ideas! I am still deciding, and I am happy to learn together.','05a8abd0-1ed0-403b-b765-d6e523f9c824','2026-10-28 03:15:02'),(329,17,2,'I am ready to try one small step today.','380729bc-5cef-46ad-8096-15e9682fe81b','2026-10-28 03:16:37'),(330,17,3,'Good plan. Take your time, and ask if you need help.','525247d7-5f24-418b-985e-3cb72f24b1ca','2026-10-28 03:16:43'),(331,17,2,'','368b64ed-f3d5-43ca-a465-19180ad00e68','2026-10-28 05:21:01');
